import { Fragment, useId, type CSSProperties } from "react"
import "./menu-deslizante.css"

interface MenuDeslizanteProps {
  items?: string[]
  defaultIndex?: number
  color?: string
  className?: string
}

function MenuDeslizante({
  items = ["Home", "About", "Contact"],
  defaultIndex = 0,
  color = "#f7e479",
  className = "",
}: MenuDeslizanteProps) {
  const name = useId()

  const style = {
    "--total-radio": items.length,
    "--main-color": color,
  } as CSSProperties

  return (
    <div className={`menu-deslizante ${className}`} style={style}>
      {items.map((item, index) => {
        const id = `${name}-${index}`
        return (
          <Fragment key={id}>
            <input
              type="radio"
              name={name}
              id={id}
              defaultChecked={index === defaultIndex}
            />
            <label htmlFor={id}>{item}</label>
          </Fragment>
        )
      })}
      <div className="menu-deslizante__glider-container">
        <div className="menu-deslizante__glider" />
      </div>
    </div>
  )
}

export { MenuDeslizante }

.menu-deslizante {
  --main-color: #f7e479;

  /* atualizado via style inline conforme a quantidade de itens */
  --total-radio: 3;

  display: flex;
  flex-direction: column;
  position: relative;
  padding-left: 0.5rem;
}

.menu-deslizante input {
  cursor: pointer;
  appearance: none;
}

.menu-deslizante .menu-deslizante__glider-container {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: linear-gradient(
    0deg,
    rgba(0, 0, 0, 0) 0%,
    rgba(27, 27, 27, 1) 50%,
    rgba(0, 0, 0, 0) 100%
  );
  width: 1px;
}

.menu-deslizante .menu-deslizante__glider-container .menu-deslizante__glider {
  position: relative;
  height: calc(100% / var(--total-radio));
  width: 100%;
  background: linear-gradient(
    0deg,
    rgba(0, 0, 0, 0) 0%,
    var(--main-color) 50%,
    rgba(0, 0, 0, 0) 100%
  );
  transition: transform 0.5s cubic-bezier(0.37, 1.95, 0.66, 0.56);
}

.menu-deslizante .menu-deslizante__glider-container .menu-deslizante__glider::before {
  content: "";
  position: absolute;
  height: 60%;
  width: 300%;
  top: 50%;
  transform: translateY(-50%);
  background: var(--main-color);
  filter: blur(10px);
}

.menu-deslizante .menu-deslizante__glider-container .menu-deslizante__glider::after {
  content: "";
  position: absolute;
  left: 0;
  height: 100%;
  width: 150px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--main-color) 11%, transparent) 0%,
    rgba(0, 0, 0, 0) 100%
  );
}

.menu-deslizante label {
  cursor: pointer;
  padding: 1rem;
  position: relative;
  color: grey;
  transition: all 0.3s ease-in-out;
}

.menu-deslizante input:checked + label {
  color: var(--main-color);
}

.menu-deslizante input:nth-of-type(1):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(0);
}

.menu-deslizante input:nth-of-type(2):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(100%);
}

.menu-deslizante input:nth-of-type(3):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(200%);
}

.menu-deslizante input:nth-of-type(4):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(300%);
}

.menu-deslizante input:nth-of-type(5):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(400%);
}

.menu-deslizante input:nth-of-type(6):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(500%);
}

.menu-deslizante input:nth-of-type(7):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(600%);
}

.menu-deslizante input:nth-of-type(8):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(700%);
}

.menu-deslizante input:nth-of-type(9):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(800%);
}

.menu-deslizante input:nth-of-type(10):checked ~ .menu-deslizante__glider-container .menu-deslizante__glider {
  transform: translateY(900%);
}
